extern "C" char* strcpy(char*, const char*);
extern "C" unsigned int strlen(const char*);

class string_buf
{
public:
  long long* data;
  int ref_count;
  int char_length;
};

class stringx
{
  char* chars;
  string_buf* my_buf;

  void make_room(int);
  friend stringx operator+(const stringx&, const char*);

public:
  stringx();
  stringx(const stringx&);
  ~stringx();
  void append(const char*, int = -1);
  void append(const stringx&);
};

inline stringx operator+(const stringx& lhs, const char* rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

class chunk_file
{
public:
  stringx get_name();
};

class chunk_flavor
{
  char flavor[16];

public:
  chunk_flavor(const char* s = "UNREG")
  {
    strcpy(flavor, s);
  }

  bool operator==(const chunk_flavor&) const;
  bool operator!=(const chunk_flavor& cf) const
  {
    return !(*this == cf);
  }
};

class entity_track_node;

class entity_track_tree
{
  char file_header[4];
  unsigned int version;
  int num_root_nodes;
  float floor_offset;

public:
  entity_track_node* insert_root();
  void _compute_duration();

  friend void serial_in(chunk_file&, entity_track_tree*);
};

extern const chunk_flavor CHUNK_END;

void serial_in(chunk_file&, chunk_flavor*);
void serial_in(chunk_file&, float*);
void serial_in(chunk_file&, entity_track_node*, entity_track_tree*);
void error(const stringx&);

void serial_in(chunk_file& fs, entity_track_tree* tree)
{
  chunk_flavor cf;
  for (serial_in(fs, &cf); cf != CHUNK_END; serial_in(fs, &cf))
  {
    if (cf == chunk_flavor("anim"))
    {
    }
    else if (cf == chunk_flavor("floor"))
    {
      serial_in(fs, &tree->floor_offset);
    }
    else if (cf == chunk_flavor("tree"))
    {
      serial_in(fs, tree->insert_root(), tree);
    }
    else
      error(fs.get_name() + ": unknown chunk found in entity_track_tree");
  }
  tree->_compute_duration();
}
